CREATE TABLE crm_lead (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, lead_no VARCHAR(64) NOT NULL, source VARCHAR(32) NOT NULL, name VARCHAR(128) NULL, phone_ciphertext VARCHAR(512) NULL, phone_hash VARCHAR(128) NULL, email VARCHAR(256) NULL, company VARCHAR(256) NULL, requirement TEXT NULL, owner_user_id BIGINT NULL, owner_team_id BIGINT NULL, status VARCHAR(32) NOT NULL, first_contact_due_at DATETIME(3) NULL, first_contact_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_lead(tenant_id,lead_no), KEY idx_lead_owner(tenant_id,owner_user_id,status), KEY idx_lead_phone(tenant_id,phone_hash));
CREATE TABLE customer (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, customer_no VARCHAR(64) NOT NULL, customer_type VARCHAR(32) NOT NULL, customer_name VARCHAR(256) NOT NULL, phone_ciphertext VARCHAR(512) NULL, phone_hash VARCHAR(128) NULL, email VARCHAR(256) NULL, company_name VARCHAR(256) NULL, source VARCHAR(32) NULL, customer_level VARCHAR(32) NULL, credit_level VARCHAR(32) NULL, owner_user_id BIGINT NULL, owner_team_id BIGINT NULL, status VARCHAR(32) NOT NULL, merged_to_customer_id BIGINT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_customer(tenant_id,customer_no), KEY idx_customer_owner(tenant_id,owner_user_id,status), KEY idx_customer_phone(tenant_id,phone_hash));
CREATE TABLE customer_contact (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, phone_ciphertext VARCHAR(512) NULL, phone_hash VARCHAR(128) NULL, email VARCHAR(256) NULL, position_name VARCHAR(128) NULL, is_primary TINYINT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, KEY idx_contact_customer(tenant_id,customer_id));
CREATE TABLE customer_merge_record (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, source_customer_id BIGINT NOT NULL, target_customer_id BIGINT NOT NULL, merge_snapshot JSON NOT NULL, merged_by BIGINT NOT NULL, merged_at DATETIME(3) NOT NULL, KEY idx_merge_source(tenant_id,source_customer_id));
CREATE TABLE customer_ownership_history (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, old_owner_id BIGINT NULL, new_owner_id BIGINT NULL, reason VARCHAR(512) NULL, changed_by BIGINT NOT NULL, changed_at DATETIME(3) NOT NULL, KEY idx_cust_owner_hist(tenant_id,customer_id,changed_at));
CREATE TABLE opportunity (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, opportunity_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, opportunity_type VARCHAR(32) NOT NULL, budget_min DECIMAL(18,2) NULL, budget_max DECIMAL(18,2) NULL, required_area_min DECIMAL(12,2) NULL, required_area_max DECIMAL(12,2) NULL, expected_start DATETIME(3) NULL, expected_end DATETIME(3) NULL, preferred_region VARCHAR(256) NULL, owner_user_id BIGINT NULL, stage VARCHAR(32) NOT NULL, stage_enter_at DATETIME(3) NOT NULL, lost_reason_code VARCHAR(64) NULL, lost_reason VARCHAR(512) NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_opp(tenant_id,opportunity_no), KEY idx_opp_owner(tenant_id,owner_user_id,stage));
CREATE TABLE opportunity_stage_history (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, opportunity_id BIGINT NOT NULL, from_stage VARCHAR(32) NULL, to_stage VARCHAR(32) NOT NULL, changed_by BIGINT NOT NULL, changed_at DATETIME(3) NOT NULL, duration_seconds BIGINT NULL, reason VARCHAR(512) NULL, KEY idx_opp_hist(tenant_id,opportunity_id,changed_at));
CREATE TABLE viewing_appointment (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, viewing_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, opportunity_id BIGINT NULL, appointment_time DATETIME(3) NOT NULL, advisor_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, arrived_at DATETIME(3) NULL, completed_at DATETIME(3) NULL, customer_feedback TEXT NULL, intention_level VARCHAR(32) NULL, advisor_comment TEXT NULL, next_follow_at DATETIME(3) NULL, UNIQUE KEY uk_viewing(tenant_id,viewing_no));
CREATE TABLE viewing_resource_relation (tenant_id BIGINT NOT NULL, viewing_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, PRIMARY KEY(tenant_id,viewing_id,resource_unit_id));
CREATE TABLE quotation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, quotation_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, opportunity_id BIGINT NOT NULL, current_version_no INT NOT NULL DEFAULT 1, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_quote(tenant_id,quotation_no));
CREATE TABLE quotation_version (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, quotation_id BIGINT NOT NULL, version_no INT NOT NULL, currency CHAR(3) NOT NULL, valid_from DATETIME(3) NOT NULL, valid_until DATETIME(3) NOT NULL, subtotal_amount DECIMAL(18,2) NOT NULL, discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL, deposit_amount DECIMAL(18,2) NOT NULL DEFAULT 0, billing_cycle_months INT NULL, status VARCHAR(32) NOT NULL, approval_instance_id VARCHAR(128) NULL, created_by BIGINT NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uk_quote_ver(tenant_id,quotation_id,version_no));
CREATE TABLE quotation_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, quotation_version_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, offering_id BIGINT NOT NULL, start_time DATETIME(3) NOT NULL, end_time DATETIME(3) NOT NULL, quantity DECIMAL(20,6) NOT NULL DEFAULT 1, unit_price DECIMAL(20,8) NOT NULL, guidance_price DECIMAL(18,2) NULL, floor_price DECIMAL(18,2) NULL, discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, final_amount DECIMAL(18,2) NOT NULL, KEY idx_quote_item_res(tenant_id,resource_unit_id));
CREATE TABLE crm_activity (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, opportunity_id BIGINT NULL, activity_type VARCHAR(32) NOT NULL, content TEXT NULL, operator_id BIGINT NOT NULL, occurred_at DATETIME(3) NOT NULL, next_follow_at DATETIME(3) NULL, KEY idx_activity_customer(tenant_id,customer_id,occurred_at));
CREATE TABLE crm_task (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, task_no VARCHAR(64) NOT NULL, customer_id BIGINT NULL, opportunity_id BIGINT NULL, task_type VARCHAR(32) NOT NULL, title VARCHAR(256) NOT NULL, due_at DATETIME(3) NULL, owner_user_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_crm_task(tenant_id,task_no), KEY idx_task_owner(tenant_id,owner_user_id,status,due_at));
